"""Order fulfillment JSON CLI entry point."""

from __future__ import annotations

import argparse
import json
import sys
import time
import uuid
import traceback

from . import OrderError, OrderService


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--db", required=True, help="Database path")
    parser.add_argument("command", help="Command to execute")
    args = parser.parse_args()

    service = OrderService(
        args.db,
        clock=time.time,
        id_factory=lambda: uuid.uuid4().hex
    )

    # Read input
    if args.command in ("init", "recover", "list"):
        # These may have empty input
        input_data = sys.stdin.read().strip()
        if not input_data:
            data = {}
        else:
            try:
                data = json.loads(input_data)
            except json.JSONDecodeError:
                output_error("INVALID_INPUT", "Invalid JSON input", {}, 2)
                return
    else:
        try:
            input_data = sys.stdin.readline().strip()
            if not input_data:
                output_error("INVALID_INPUT", "Empty input", {}, 2)
                return
            data = json.loads(input_data)
        except json.JSONDecodeError:
            output_error("INVALID_INPUT", "Invalid JSON input", {}, 2)
            return

    if not isinstance(data, dict):
        output_error("INVALID_INPUT", "Input must be JSON object", {}, 2)
        return

    try:
        result = execute_command(service, args.command, data)
        output_success(result)
    except OrderError as e:
        output_error(e.code, e.message, e.details, 2)
    except Exception as e:
        # Unexpected error - use STORAGE_ERROR code with exit 3
        output_error("STORAGE_ERROR", "Internal error", {"error": str(e)}, 3)


def execute_command(service, command: str, data: dict):
    """Execute the specified command."""
    if command == "stock":
        validate_fields(data, ["sku", "quantity"])
        return service.set_stock(data["sku"], data["quantity"])

    elif command == "create":
        validate_fields(data, ["idempotency_key", "items"])
        return service.create_order(data["idempotency_key"], data["items"])

    elif command == "pay":
        validate_fields(data, ["order_id", "payment_id", "amount_cents"])
        return service.pay_order(data["order_id"], data["payment_id"], data["amount_cents"])

    elif command == "cancel":
        validate_fields(data, ["order_id"])
        return service.cancel_order(data["order_id"])

    elif command == "ship":
        validate_fields(data, ["order_id"])
        return service.ship_order(data["order_id"])

    elif command == "get":
        validate_fields(data, ["order_id"])
        return service.get_order(data["order_id"])

    else:
        raise OrderError("INVALID_INPUT", f"Unknown command: {command}")


def validate_fields(data: dict, required: list[str]) -> None:
    """Validate required fields are present."""
    for field in required:
        if field not in data:
            raise OrderError("INVALID_INPUT", f"Missing required field: {field}")


def output_success(result) -> None:
    """Output success response."""
    response = {"ok": True, "result": result}
    print(json.dumps(response, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False))
    sys.exit(0)


def output_error(code: str, message: str, details: dict, exit_code: int) -> None:
    """Output error response."""
    response = {
        "ok": False,
        "error": {
            "code": code,
            "message": message,
            "details": details
        }
    }
    print(json.dumps(response, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False))
    sys.exit(exit_code)


if __name__ == "__main__":
    main()

