"""Delivery spool service."""

from __future__ import annotations

import fcntl
import json
import math
import os
import secrets
import time as _time
import uuid
from dataclasses import dataclass
from typing import Any, Callable


@dataclass(frozen=True)
class Limits:
    max_messages: int = 10000
    max_payload_bytes: int = 65536
    max_attempts: int = 5
    lease_seconds: float = 30.0
    retry_delay: float = 10.0

    def __post_init__(self) -> None:
        """Validate limits."""
        if not isinstance(self.max_messages, int) or isinstance(self.max_messages, bool) or self.max_messages <= 0:
            raise ValueError("max_messages must be positive integer")
        if not isinstance(self.max_payload_bytes, int) or isinstance(self.max_payload_bytes, bool) or self.max_payload_bytes <= 0:
            raise ValueError("max_payload_bytes must be positive integer")
        if not isinstance(self.max_attempts, int) or isinstance(self.max_attempts, bool) or self.max_attempts <= 0:
            raise ValueError("max_attempts must be positive integer")
        if not isinstance(self.lease_seconds, (int, float)) or math.isinf(self.lease_seconds) or math.isnan(self.lease_seconds) or self.lease_seconds <= 0:
            raise ValueError("lease_seconds must be positive finite number")
        if not isinstance(self.retry_delay, (int, float)) or math.isinf(self.retry_delay) or math.isnan(self.retry_delay) or self.retry_delay < 0:
            raise ValueError("retry_delay must be non-negative finite number")


class SpoolError(Exception):
    """Stable spool-domain error."""

    def __init__(self, code: str, message: str, details: dict[str, object] | None = None):
        self.code = code
        self.message = message
        self.details = details if details is not None else {}
        super().__init__(message)

    def __str__(self) -> str:
        return self.message


class Spool:
    """Filesystem-backed lease spool."""

    VALID_STATUSES = {"pending", "leased", "acked", "dead"}
    SCHEMA_VERSION = 1

    def __init__(self, root, *, clock, limits, lock_timeout, failpoint):
        self.root = root
        self.clock = clock
        self.limits = limits
        self.lock_timeout = lock_timeout
        self.failpoint = failpoint

        # Validate lock_timeout
        if not isinstance(lock_timeout, (int, float)) or math.isinf(lock_timeout) or math.isnan(lock_timeout) or lock_timeout < 0:
            raise SpoolError("INVALID_INPUT", "lock_timeout must be non-negative finite number")

        # Validate limits is Limits instance
        if not isinstance(limits, Limits):
            raise SpoolError("INVALID_INPUT", "limits must be Limits instance")

    def _validate_clock(self) -> float:
        """Validate and return clock value."""
        value = self.clock()
        if not isinstance(value, (int, float)) or math.isinf(value) or math.isnan(value):
            raise SpoolError("INVALID_DEPENDENCY", "clock must return finite number")
        return float(value)

    def _validate_non_empty_string(self, name: str, value: str) -> None:
        """Validate string is non-empty and not just whitespace."""
        if not isinstance(value, str) or not value or value.isspace():
            raise SpoolError("INVALID_INPUT", f"{name} must be non-empty non-whitespace string")

    def _validate_payload(self, payload) -> bytes:
        """Validate and canonicalize payload, return bytes."""
        try:
            canonical = json.dumps(
                payload,
                sort_keys=True,
                separators=(",", ":"),
                ensure_ascii=False,
                allow_nan=False
            ).encode("utf-8")
        except (TypeError, ValueError) as e:
            raise SpoolError("INVALID_INPUT", "Invalid JSON payload", {"error": str(e)}) from e

        if len(canonical) > self.limits.max_payload_bytes:
            raise SpoolError("INVALID_INPUT", f"Payload exceeds max size: {len(canonical)} > {self.limits.max_payload_bytes}")

        return canonical

    def _validate_status(self, status) -> None:
        """Validate status is valid."""
        if status is not None and status not in self.VALID_STATUSES:
            raise SpoolError("INVALID_INPUT", f"Invalid status: {status}")

    def _canonical_payload(self, payload) -> str:
        """Get canonical payload string."""
        return json.dumps(
            payload,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
            allow_nan=False
        )

    def _state_path(self) -> str:
        """Get path to state.json."""
        return os.path.join(self.root, "state.json")

    def _lock_path(self) -> str:
        """Get path to state.lock."""
        return os.path.join(self.root, "state.lock")

    def _acquire_lock(self):
        """Acquire exclusive lock with timeout."""
        os.makedirs(self.root, exist_ok=True)
        lock_path = self._lock_path()

        lock_file = open(lock_path, "w")

        start = _time.time()
        while True:
            try:
                fcntl.flock(lock_file.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
                return lock_file
            except BlockingIOError:
                elapsed = _time.time() - start
                if elapsed >= self.lock_timeout:
                    lock_file.close()
                    raise SpoolError("LOCK_TIMEOUT", "Failed to acquire lock within timeout")
                _time.sleep(0.01)

    def _release_lock(self, lock_file) -> None:
        """Release lock."""
        try:
            fcntl.flock(lock_file.fileno(), fcntl.LOCK_UN)
        finally:
            lock_file.close()

    def _call_failpoint(self, name: str) -> None:
        """Call failpoint if set."""
        if self.failpoint is not None:
            self.failpoint(name)

    def _cleanup_temp_files(self) -> None:
        """Clean up any leftover temp files."""
        try:
            for filename in os.listdir(self.root):
                if filename.startswith(".state.") and filename.endswith(".tmp"):
                    os.remove(os.path.join(self.root, filename))
        except OSError:
            pass

    def _read_state(self) -> dict:
        """Read and validate state from disk."""
        state_path = self._state_path()

        if not os.path.exists(state_path):
            raise SpoolError("NOT_INITIALIZED", "Spool not initialized")

        try:
            with open(state_path, "r", encoding="utf-8") as f:
                content = f.read()
                state = json.loads(content)
        except json.JSONDecodeError as e:
            raise SpoolError("CORRUPT_STATE", "Invalid JSON in state file", {"error": str(e)}) from e
        except OSError as e:
            raise SpoolError("INTERNAL_ERROR", "Failed to read state", {"error": str(e)}) from e

        return self._validate_state(state)

    def _validate_state(self, state: dict) -> dict:
        """Validate state structure."""
        if not isinstance(state, dict):
            raise SpoolError("CORRUPT_STATE", "State must be dict")

        if state.get("schema_version") != self.SCHEMA_VERSION:
            raise SpoolError("SCHEMA_MISMATCH", f"Unexpected schema version: {state.get('schema_version')}")

        if not isinstance(state.get("next_sequence"), int) or state["next_sequence"] < 1:
            raise SpoolError("CORRUPT_STATE", "Invalid next_sequence")

        if not isinstance(state.get("messages"), dict):
            raise SpoolError("CORRUPT_STATE", "messages must be dict")

        for msg_id, msg in state["messages"].items():
            self._validate_message(msg_id, msg)

        return state

    def _validate_message(self, msg_id: str, msg: dict) -> None:
        """Validate message structure."""
        if not isinstance(msg, dict):
            raise SpoolError("CORRUPT_STATE", f"Invalid message for {msg_id}")

        required = {"message_id", "payload", "status", "available_at", "sequence", "attempts", "last_error"}
        if set(msg.keys()) != required:
            raise SpoolError("CORRUPT_STATE", f"Invalid message fields for {msg_id}: {set(msg.keys())}")

        if msg["status"] not in self.VALID_STATUSES:
            raise SpoolError("CORRUPT_STATE", f"Invalid status for {msg_id}: {msg['status']}")

        if not isinstance(msg["sequence"], int) or msg["sequence"] < 1:
            raise SpoolError("CORRUPT_STATE", f"Invalid sequence for {msg_id}")

        if not isinstance(msg["attempts"], int) or msg["attempts"] < 0:
            raise SpoolError("CORRUPT_STATE", f"Invalid attempts for {msg_id}")

    def _write_state(self, state: dict, lock_file) -> None:
        """Atomically write state to disk."""
        # Create temp file in same directory
        temp_name = f".state.{os.getpid()}.{uuid.uuid4().hex}.tmp"
        temp_path = os.path.join(self.root, temp_name)

        try:
            # Write to temp file
            with open(temp_path, "w", encoding="utf-8") as f:
                json.dump(
                    state,
                    f,
                    sort_keys=True,
                    separators=(",", ":"),
                    ensure_ascii=False,
                    allow_nan=False
                )
                f.write("\n")
                f.flush()
                os.fsync(f.fileno())

            # Failpoint before replace
            self._call_failpoint("before_replace")

            # Atomic replace
            os.replace(temp_path, self._state_path())

            # Failpoint after replace
            self._call_failpoint("after_replace")

            # Fsync directory
            try:
                dir_fd = os.open(self.root, os.O_RDONLY | os.O_DIRECTORY)
                try:
                    os.fsync(dir_fd)
                finally:
                    os.close(dir_fd)
            except OSError:
                pass
        finally:
            # Clean up temp file if it still exists
            try:
                if os.path.exists(temp_path):
                    os.remove(temp_path)
            except OSError:
                pass

    def _build_public_message(self, msg: dict, include_lease: bool = False) -> dict:
        """Build public message response."""
        result = {
            "message_id": msg["message_id"],
            "payload": msg["payload"],
            "status": msg["status"],
            "available_at": msg["available_at"],
            "sequence": msg["sequence"],
            "attempts": msg["attempts"],
            "last_error": msg["last_error"]
        }

        if include_lease and "lease_token" in msg:
            result["lease_token"] = msg["lease_token"]

        return result

    def _constant_time_compare(self, a: str, b: str) -> bool:
        """Constant-time string comparison for tokens."""
        return secrets.compare_digest(a.encode("utf-8"), b.encode("utf-8"))

    def _generate_lease_token(self) -> str:
        """Generate secure lease token."""
        return secrets.token_hex(32)

    def initialize(self) -> dict:
        """Initialize the spool."""
        lock_file = None
        try:
            lock_file = self._acquire_lock()
            self._call_failpoint("after_lock")

            # Check if already initialized
            try:
                self._read_state()
                raise SpoolError("ALREADY_INITIALIZED", "Spool already initialized")
            except SpoolError as e:
                if e.code != "NOT_INITIALIZED":
                    raise

            # Create initial state
            state = {
                "schema_version": self.SCHEMA_VERSION,
                "next_sequence": 1,
                "messages": {}
            }

            self._write_state(state, lock_file)

            return {"initialized": True}
        finally:
            self._cleanup_temp_files()
            if lock_file:
                self._release_lock(lock_file)

    def enqueue(self, message_id: str, payload, available_at=None) -> dict:
        """Enqueue a message."""
        self._validate_non_empty_string("message_id", message_id)

        # Canonicalize and validate payload
        payload_canonical = self._validate_payload(payload)
        # Re-parse to get the actual dict to store
        stored_payload = json.loads(payload_canonical)

        if available_at is None:
            available_at = self._validate_clock()
        else:
            if not isinstance(available_at, (int, float)) or math.isinf(available_at) or math.isnan(available_at):
                raise SpoolError("INVALID_INPUT", "available_at must be finite number")
            available_at = float(available_at)

        lock_file = None
        try:
            lock_file = self._acquire_lock()
            self._call_failpoint("after_lock")

            state = self._read_state()

            # Check for existing message
            if message_id in state["messages"]:
                existing = state["messages"][message_id]
                # Check if identical
                existing_payload_str = self._canonical_payload(existing["payload"])
                new_payload_str = payload_canonical.decode("utf-8")

                if existing_payload_str == new_payload_str and existing["available_at"] == available_at:
                    # Return existing unchanged
                    return self._build_public_message(existing)
                else:
                    raise SpoolError("IDEMPOTENCY_CONFLICT", f"Message ID {message_id} already exists with different content")

            # Check capacity
            if len(state["messages"]) >= self.limits.max_messages:
                raise SpoolError("CAPACITY_EXCEEDED", f"Max messages exceeded: {self.limits.max_messages}")

            # Create new message
            sequence = state["next_sequence"]
            state["next_sequence"] += 1

            message = {
                "message_id": message_id,
                "payload": stored_payload,
                "status": "pending",
                "available_at": available_at,
                "sequence": sequence,
                "attempts": 0,
                "last_error": None,
                "lease_token": None,
                "worker_id": None,
                "expires_at": None
            }

            state["messages"][message_id] = message

            self._write_state(state, lock_file)

            return self._build_public_message(message)
        finally:
            self._cleanup_temp_files()
            if lock_file:
                self._release_lock(lock_file)

    def claim(self, worker_id: str) -> dict | None:
        """Claim next available message."""
        self._validate_non_empty_string("worker_id", worker_id)

        now = self._validate_clock()

        lock_file = None
        try:
            lock_file = self._acquire_lock()
            self._call_failpoint("after_lock")

            state = self._read_state()

            # Find pending messages where available_at <= now
            candidates = []
            for msg in state["messages"].values():
                if msg["status"] == "pending" and msg["available_at"] <= now:
                    candidates.append(msg)

            if not candidates:
                return None

            # Sort by (available_at, sequence, message_id) and pick first
            candidates.sort(key=lambda m: (m["available_at"], m["sequence"], m["message_id"]))
            msg = candidates[0]

            # Update message
            msg["status"] = "leased"
            msg["attempts"] += 1
            msg["worker_id"] = worker_id
            msg["lease_token"] = self._generate_lease_token()
            msg["expires_at"] = now + self.limits.lease_seconds
            msg["last_error"] = None

            self._write_state(state, lock_file)

            # Return with lease_token
            result = self._build_public_message(msg, include_lease=True)
            return result
        finally:
            self._cleanup_temp_files()
            if lock_file:
                self._release_lock(lock_file)

    def ack(self, message_id: str, lease_token: str) -> dict:
        """Acknowledge message as processed."""
        self._validate_non_empty_string("message_id", message_id)
        self._validate_non_empty_string("lease_token", lease_token)

        lock_file = None
        try:
            lock_file = self._acquire_lock()
            self._call_failpoint("after_lock")

            state = self._read_state()

            if message_id not in state["messages"]:
                raise SpoolError("NOT_FOUND", f"Message {message_id} not found")

            msg = state["messages"][message_id]

            # Must be leased
            if msg["status"] != "leased":
                raise SpoolError("INVALID_STATE", f"Message is not leased: {msg['status']}")

            # Verify token with constant-time comparison
            if not self._constant_time_compare(msg["lease_token"], lease_token):
                raise SpoolError("UNAUTHORIZED", "Invalid lease token")

            # Mark as acked
            msg["status"] = "acked"
            msg["lease_token"] = None
            msg["worker_id"] = None
            msg["expires_at"] = None

            self._write_state(state, lock_file)

            return self._build_public_message(msg)
        finally:
            self._cleanup_temp_files()
            if lock_file:
                self._release_lock(lock_file)

    def fail(self, message_id: str, lease_token: str, error: str) -> dict:
        """Mark message as failed."""
        self._validate_non_empty_string("message_id", message_id)
        self._validate_non_empty_string("lease_token", lease_token)
        self._validate_non_empty_string("error", error)

        lock_file = None
        try:
            lock_file = self._acquire_lock()
            self._call_failpoint("after_lock")

            state = self._read_state()

            if message_id not in state["messages"]:
                raise SpoolError("NOT_FOUND", f"Message {message_id} not found")

            msg = state["messages"][message_id]

            # Must be leased
            if msg["status"] != "leased":
                raise SpoolError("INVALID_STATE", f"Message is not leased: {msg['status']}")

            # Verify token with constant-time comparison
            if not self._constant_time_compare(msg["lease_token"], lease_token):
                raise SpoolError("UNAUTHORIZED", "Invalid lease token")

            now = self._validate_clock()

            # Record error
            msg["last_error"] = error
            msg["lease_token"] = None
            msg["worker_id"] = None
            msg["expires_at"] = None

            # Check if max attempts reached
            if msg["attempts"] >= self.limits.max_attempts:
                msg["status"] = "dead"
            else:
                msg["status"] = "pending"
                msg["available_at"] = now + self.limits.retry_delay

            self._write_state(state, lock_file)

            return self._build_public_message(msg)
        finally:
            self._cleanup_temp_files()
            if lock_file:
                self._release_lock(lock_file)

    def recover(self) -> dict:
        """Recover expired leases."""
        now = self._validate_clock()

        lock_file = None
        try:
            lock_file = self._acquire_lock()
            self._call_failpoint("after_lock")

            state = self._read_state()

            recovered_count = 0

            for msg in state["messages"].values():
                if msg["status"] == "leased" and msg["expires_at"] <= now:
                    recovered_count += 1

                    # Clear lease fields
                    msg["lease_token"] = None
                    msg["worker_id"] = None
                    msg["expires_at"] = None

                    # Check if dead
                    if msg["attempts"] >= self.limits.max_attempts:
                        msg["status"] = "dead"
                    else:
                        msg["status"] = "pending"
                        msg["available_at"] = now

            if recovered_count > 0:
                self._write_state(state, lock_file)

            return {"recovered": recovered_count}
        finally:
            self._cleanup_temp_files()
            if lock_file:
                self._release_lock(lock_file)

    def get(self, message_id: str) -> dict:
        """Get message by ID."""
        self._validate_non_empty_string("message_id", message_id)

        lock_file = None
        try:
            lock_file = self._acquire_lock()
            self._call_failpoint("after_lock")

            state = self._read_state()

            if message_id not in state["messages"]:
                raise SpoolError("NOT_FOUND", f"Message {message_id} not found")

            return self._build_public_message(state["messages"][message_id])
        finally:
            self._cleanup_temp_files()
            if lock_file:
                self._release_lock(lock_file)

    def list_messages(self, status=None) -> list[dict]:
        """List messages optionally filtered by status."""
        self._validate_status(status)

        lock_file = None
        try:
            lock_file = self._acquire_lock()
            self._call_failpoint("after_lock")

            state = self._read_state()

            messages = []
            for msg in state["messages"].values():
                if status is None or msg["status"] == status:
                    messages.append(msg)

            # Sort by (available_at, sequence, message_id)
            messages.sort(key=lambda m: (m["available_at"], m["sequence"], m["message_id"]))

            return [self._build_public_message(m) for m in messages]
        finally:
            self._cleanup_temp_files()
            if lock_file:
                self._release_lock(lock_file)


