"""Delivery spool JSON CLI entry point."""

from __future__ import annotations

import argparse
import json
import sys
import time

from . import Limits, Spool, SpoolError


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--root", required=True, help="Spool root directory")
    parser.add_argument("command", help="Command to execute")
    args = parser.parse_args()

    spool = Spool(
        args.root,
        clock=time.time,
        limits=Limits(),
        lock_timeout=10.0,
        failpoint=None
    )

    # Read input
    if args.command in ("init", "recover", "list"):
        # These may have empty input
        input_data = sys.stdin.read().strip()
        if not input_data:
            data = {}
        else:
            try:
                data = json.loads(input_data)
            except json.JSONDecodeError:
                output_error("INVALID_INPUT", "Invalid JSON input", {}, 2)
                return
    else:
        try:
            input_data = sys.stdin.readline().strip()
            if not input_data:
                output_error("INVALID_INPUT", "Empty input", {}, 2)
                return
            data = json.loads(input_data)
        except json.JSONDecodeError:
            output_error("INVALID_INPUT", "Invalid JSON input", {}, 2)
            return

    if not isinstance(data, dict):
        output_error("INVALID_INPUT", "Input must be JSON object", {}, 2)
        return

    try:
        result = execute_command(spool, args.command, data)
        output_success(result)
    except SpoolError as e:
        # Determine exit code
        if e.code in ("CORRUPT_STATE", "LOCK_TIMEOUT", "INTERNAL_ERROR"):
            exit_code = 3
        else:
            exit_code = 2
        output_error(e.code, e.message, e.details, exit_code)
    except Exception as e:
        output_error("INTERNAL_ERROR", "Internal error", {"error": str(e)}, 3)


def execute_command(spool, command: str, data: dict):
    """Execute the specified command."""
    if command == "init":
        return spool.initialize()

    elif command == "enqueue":
        validate_fields(data, ["message_id", "payload"])
        return spool.enqueue(
            data["message_id"],
            data["payload"],
            data.get("available_at")
        )

    elif command == "claim":
        validate_fields(data, ["worker_id"])
        return spool.claim(data["worker_id"])

    elif command == "ack":
        validate_fields(data, ["message_id", "lease_token"])
        return spool.ack(data["message_id"], data["lease_token"])

    elif command == "fail":
        validate_fields(data, ["message_id", "lease_token", "error"])
        return spool.fail(data["message_id"], data["lease_token"], data["error"])

    elif command == "recover":
        return spool.recover()

    elif command == "show":
        validate_fields(data, ["message_id"])
        return spool.get(data["message_id"])

    elif command == "list":
        return spool.list_messages(data.get("status"))

    else:
        raise SpoolError("INVALID_INPUT", f"Unknown command: {command}")


def validate_fields(data: dict, required: list[str]) -> None:
    """Validate required fields are present."""
    for field in required:
        if field not in data:
            raise SpoolError("INVALID_INPUT", f"Missing required field: {field}")


def output_success(result) -> None:
    """Output success response."""
    response = {"ok": True, "result": result}
    print(json.dumps(response, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False))
    sys.exit(0)


def output_error(code: str, message: str, details: dict, exit_code: int) -> None:
    """Output error response."""
    response = {
        "ok": False,
        "error": {
            "code": code,
            "message": message,
            "details": details
        }
    }
    print(json.dumps(response, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False))
    sys.exit(exit_code)


if __name__ == "__main__":
    main()

